parameters.jsCode:
const text = $input.item.json.output;

const converted = text
  // Заголовки ### → **жирный текст**
  .replace(/^#{1,6}\s+(.+)$/gm, '*$1*')
  // Жирный **текст** уже поддерживается, оставляем
  // Убираем лишние пустые строки (больше 2 подряд)
  .replace(/\n{3,}/g, '\n\n')
  // Горизонтальные разделители --- убираем
  .replace(/^[-*_]{3,}$/gm, '');

return [{ json: { output: converted } }];

conditions.leftValue:
={{ (() => {
  const msg = ($json.message?.text || '').toLowerCase();
  const triggers = ['возврат', 'суд', 'паника', 'паническая атака', 'болит', 'таблетки', 'врач', 'умираю', 'отмена', 'отменить', 'перенос', 'страшно', 'тревога'];
  // Английские слова — целыми словами, чтобы «painting» не сработал как «pain»
  const en = /\b(refund|cancel|cancellation|reschedule|lawsuit|court|panic|panic attack|hurts?|pain|pills|doctor|dying|scared|anxiety|emergency)\b/;
  return triggers.some(word => msg.includes(word)) || en.test(msg);
})() }}

