assignments.value:
={{ (() => {
  const m = $json.message || {};
  const t = m.text || '';
  if (/^\/start\s+en\b/i.test(t)) return 'en';
  if (/^\/start\s+ru\b/i.test(t)) return 'ru';
  if (/[А-Яа-яЁё]/.test(t)) return 'ru';
  if ((t.match(/[A-Za-z]{2,}/g) || []).length >= 3) return 'en';
  const c = (m.from?.language_code || '').toLowerCase();
  return (!c || /^(ru|uk|be|kk)/.test(c)) ? 'ru' : 'en';
})() }}
